# Suggested hardened version of `app.js`

Below is a more secure baseline. Some parts, especially JWT authentication, require environment variables and additional packages.

```js
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');

const app = express();

app.disable('x-powered-by');

app.use(helmet());

app.use(express.json({
  limit: '100kb',
}));

const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 300,
  standardHeaders: true,
  legacyHeaders: false,
});

const sensitiveLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 60,
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(generalLimiter);

function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or invalid authorization header' });
  }

  const token = authHeader.slice('Bearer '.length);

  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET, {
      algorithms: ['HS256'],
    });

    req.user = payload;
    next();
  } catch {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

function requireRole(role) {
  return (req, res, next) => {
    if (!req.user || req.user.role !== role) {
      return res.status(403).json({ error: 'Forbidden' });
    }

    next();
  };
}

function getUsers() {
  return [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.get('/users', sensitiveLimiter, authenticate, requireRole('admin'), (req, res) => {
  console.info('Users list accessed', {
    actor: req.user.sub,
    role: req.user.role,
    time: new Date().toISOString(),
  });

  res.json(getUsers());
});

app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

app.use((err, req, res, next) => {
  console.error(err);

  res.status(err.status || 500).json({
    error: 'Internal Server Error',
  });
});

const port = Number(process.env.PORT) || 3000;
const host = process.env.HOST || '127.0.0.1';

if (require.main === module) {
  app.listen(port, host, () => {
    console.log(`Server running on ${host}:${port}`);
  });
}

module.exports = app;
```

Required packages:

```bash
npm install helmet express-rate-limit jsonwebtoken
```

---

# Additional production recommendations

1. **Use HTTPS**
   - Usually terminate TLS at a load balancer or reverse proxy.
   - Redirect HTTP to HTTPS at the edge.

2. **Store secrets securely**
   - Use environment variables or a secret manager.
   - Never commit JWT secrets, API keys, or passwords.

3. **Audit dependencies**
   - Add a `package.json`.
   - Run:

   ```bash
   npm audit
   ```

4. **Add tests for security behavior**
   - `/users` should return `401` without a token.
   - `/users` should return `403` for non-admin users.
   - `/health` should not expose sensitive internals.

5. **Avoid returning unnecessary user fields**
   - If consumers do not need email addresses, omit them.
   - Prefer least-privilege response design.

6. **Use structured logging**
   - Log security-relevant events.
   - Do not log access tokens, passwords, or secrets.

---

