    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

Even though the data is hardcoded, this is still personally identifiable information. If this endpoint later connects to a real user database, the issue becomes more serious.

### OWASP category

- A01: Broken Access Control
- A07: Identification and Authentication Failures
- A02: Cryptographic Failures, if sensitive user data is leaked

### Recommendation

Require authentication before returning user data.

Example API key middleware:

```js
function requireApiKey(req, res, next) {
  const providedKey = req.get('x-api-key');

  if (!providedKey || providedKey !== process.env.API_KEY) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  next();
}

app.get('/users', requireApiKey, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

For a real production application, prefer a standard authentication mechanism such as:

- OAuth2 / OpenID Connect
- JWT access tokens with signature verification
- Session-based auth with secure cookies

Example JWT middleware:

```js
const jwt = require('jsonwebtoken');

function requireAuth(req, res, next) {
  const authHeader = req.get('authorization');

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }

  const token = authHeader.slice('Bearer '.length);

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET, {
      algorithms: ['HS256'],
    });
    next();
  } catch {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

app.get('/users', requireAuth, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

## 2. No authorization checks

### Risk

Authentication answers: “Who are you?”

Authorization answers: “Are you allowed to do this?”

Even if authentication is added, `/users` should not automatically be available to every authenticated user. For example, a normal user should not be able to list every other user’s email address.

### OWASP category

- A01: Broken Access Control

### Recommendation

Implement role-based or permission-based authorization.

Example:

```js
function requireRole(role) {
  return function (req, res, next) {
    if (!req.user || req.user.role !== role) {
      return res.status(403).json({ error: 'Forbidden' });
    }

    next();
  };
}

app.get('/users', requireAuth, requireRole('admin'), (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

If users should only access their own profile, use a route like this instead:

```js
app.get('/users/me', requireAuth, (req, res) => {
  res.json({
    id: req.user.sub,
    name: req.user.name,
    email: req.user.email,
  });
});
```

---

## 3. No security headers

### Risk

Express does not set many important HTTP security headers by default. Missing headers can increase exposure to:

- Cross-site scripting impact
- Clickjacking
- MIME sniffing
- Information leakage
- Browser-based attacks

### OWASP category

- A05: Security Misconfiguration

### Recommendation

Use `helmet`.

Install:

```bash
npm install helmet
```

Add near the top of `app.js`:

```js
const helmet = require('helmet');

app.use(helmet());
```

A more explicit configuration could look like:

```js
app.use(
  helmet({
    contentSecurityPolicy: false, // Often unnecessary for pure JSON APIs
    crossOriginResourcePolicy: { policy: 'same-site' },
  })
);
```

For a JSON-only API, the default Helmet settings are usually a good starting point.

---

## 4. No rate limiting

### Risk

The application has no protection against request flooding or brute force attacks. Even though there is no login endpoint currently, public endpoints can still be abused for:

- Denial of service
- Enumeration
- Scraping
- Resource exhaustion

### OWASP category

- A04: Insecure Design
- A05: Security Misconfiguration

### Recommendation

Use rate limiting.

Install:

```bash
npm install express-rate-limit
```

Example:

```js
const rateLimit = require('express-rate-limit');

const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests' },
});

app.use(generalLimiter);
```

For sensitive endpoints, use stricter limits:

```js
const sensitiveLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  standardHeaders: true,
  legacyHeaders: false,
});

app.get('/users', sensitiveLimiter, requireAuth, requireRole('admin'), (req, res) => {
  res.json([]);
});
```

---

## 5. No input validation framework

### Risk

The current routes do not accept user input, so there is no direct injection issue today. However, the app has no pattern for validating:

- Request bodies
- Query parameters
- Path parameters
- Headers

This becomes important as soon as routes like these are added:

```js
app.get('/users/:id', ...)
app.post('/users', ...)
app.get('/search?q=...', ...)
```

### OWASP category

- A03: Injection
- A04: Insecure Design

### Recommendation

Adopt a validation library such as `zod`, `joi`, or `express-validator`.

Example with `zod`:

Install:

```bash
npm install zod
```

Example validation middleware:

```js
const { z } = require('zod');

function validateParams(schema) {
  return function (req, res, next) {
    const result = schema.safeParse(req.params);

    if (!result.success) {
      return res.status(400).json({
        error: 'Invalid request parameters',
        details: result.error.flatten(),
      });
    }

    req.params = result.data;
    next();
  };
}

const userIdParamsSchema = z.object({
  id: z.coerce.number().int().positive(),
});

app.get('/users/:id', requireAuth, validateParams(userIdParamsSchema), (req, res) => {
  const userId = req.params.id;

  res.json({
    id: userId,
    name: 'Alice',
    email: 'alice@example.com',
  });
});
```

For JSON request bodies:

```js
app.use(express.json({ limit: '100kb' }));

function validateBody(schema) {
  return function (req, res, next) {
    const result = schema.safeParse(req.body);

    if (!result.success) {
      return res.status(400).json({
        error: 'Invalid request body',
        details: result.error.flatten(),
      });
    }

    req.body = result.data;
    next();
  };
}

const createUserSchema = z.object({
  name: z.string().trim().min(1).max(100),
  email: z.string().trim().email().max(254),
});

app.post('/users', requireAuth, requireRole('admin'), validateBody(createUserSchema), (req, res) => {
  res.status(201).json({
    id: 3,
    name: req.body.name,
    email: req.body.email,
  });
});
```

---

## 6. No explicit JSON body size limit

### Risk

The current app does not use `express.json()`, so this is not currently exploitable through JSON body parsing. But most APIs eventually add:

```js
app.use(express.json());
```

Using it without a limit can expose the app to memory exhaustion attacks from large request bodies.

### OWASP category

- A05: Security Misconfiguration

### Recommendation

If JSON parsing is added, set a small explicit limit:

```js
app.use(express.json({ limit: '100kb' }));
```

If URL-encoded forms are added:

```js
app.use(express.urlencoded({ extended: false, limit: '100kb' }));
```

---

## 7. No centralized error handler

### Risk

The current app has no explicit error handler. Express’s default error handler may expose stack traces in development. As the app grows, uncaught errors could result in inconsistent responses or accidental information disclosure.

### OWASP category

- A05: Security Misconfiguration
- A09: Security Logging and Monitoring Failures

### Recommendation

Add a centralized error handler that:

- Logs the full internal error server-side
- Returns generic errors to clients
- Avoids leaking stack traces in production

Example:

```js
app.use((err, req, res, next) => {
  console.error('Unhandled application error:', err);

  res.status(err.status || 500).json({
    error: 'Internal server error',
  });
});
```

For async route handlers, use a wrapper:

```js
function asyncHandler(fn) {
  return function (req, res, next) {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

app.get('/users', requireAuth, asyncHandler(async (req, res) => {
  const users = await loadUsers();
  res.json(users);
}));
```

---

## 8. Server always listens on hardcoded port `3000`

### Risk

This is not a direct security vulnerability, but it creates operational issues:

```js
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

Problems:

- Cannot easily run behind platform-assigned ports
- Harder to separate test and runtime behavior
- Importing `app.js` in tests starts a real server
- Can cause accidental exposure if run in the wrong environment

### OWASP category

- A05: Security Misconfiguration

### Recommendation

Use an environment variable for the port and avoid listening when the app is imported as a module.

```js
const port = process.env.PORT || 3000;

if (require.main === module) {
  app.listen(port, () => {
    console.log(`Server running on port ${port}`);
  });
}

module.exports = app;
```

---

## 9. No CORS policy

### Risk

By default, Express does not send permissive CORS headers, which is safer than allowing everything. However, if CORS is later added with `origin: '*'`, sensitive authenticated endpoints may become unnecessarily exposed to browser-based cross-origin calls.

### OWASP category

- A05: Security Misconfiguration

### Recommendation

If browser clients need cross-origin access, configure CORS explicitly.

Install:

```bash
npm install cors
```

Example:

```js
const cors = require('cors');

const allowedOrigins = [
  'https://example.com',
  'https://admin.example.com',
];

app.use(
  cors({
    origin(origin, callback) {
      if (!origin || allowedOrigins.includes(origin)) {
        return callback(null, true);
      }

      return callback(new Error('Not allowed by CORS'));
    },
    methods: ['GET'],
    allowedHeaders: ['Authorization', 'Content-Type'],
    credentials: false,
  })
);
```

If using cookies for auth, set `credentials: true` only with specific trusted origins, never with wildcard origins.

---

## 10. No logging or monitoring strategy

### Risk

The app does not log requests, authentication failures, authorization failures, or errors. This makes abuse and incidents difficult to detect.

### OWASP category

- A09: Security Logging and Monitoring Failures

### Recommendation

Add structured request logging and security event logging.

Example with `morgan`:

Install:

```bash
npm install morgan
```

Use:

```js
const morgan = require('morgan');

app.use(morgan('combined'));
```

For authentication failures:

```js
function requireApiKey(req, res, next) {
  const providedKey = req.get('x-api-key');

  if (!providedKey || providedKey !== process.env.API_KEY) {
    console.warn('Unauthorized request', {
      ip: req.ip,
      path: req.originalUrl,
    });

    return res.status(401).json({ error: 'Unauthorized' });
  }

  next();
}
```

Avoid logging secrets, tokens, passwords, or full authorization headers.

---

## 11. Potential injection risks in future changes

### Current status

There is currently no database query, shell command execution, template rendering, or dynamic evaluation. Therefore, common injection classes are not currently present in `app.js`.

However, injection vulnerabilities can easily appear when the app is extended.

### SQL injection example to avoid

Do not write:

```js
const query = `SELECT * FROM users WHERE id = ${req.params.id}`;
```

Use parameterized queries instead:

```js
const result = await db.query(
  'SELECT id, name, email FROM users WHERE id = $1',
  [req.params.id]
);
```

### NoSQL injection example to avoid

Do not pass untrusted objects directly into queries:

```js
const user = await User.findOne({ email: req.body.email });
```

Validate that `email` is a string first:

```js
const schema = z.object({
  email: z.string().email(),
});

const { email } = schema.parse(req.body);

const user = await User.findOne({ email });
```

### Command injection example to avoid

Do not write:

```js
const output = execSync(`grep ${req.query.term} file.txt`);
```

Prefer APIs that do not invoke a shell:

```js
const { execFile } = require('child_process');

execFile('grep', [req.query.term, 'file.txt'], (error, stdout) => {
  // handle safely
});
```

Also validate `req.query.term`.

---

## 12. Data minimization issue

### Risk

The `/users` endpoint returns email addresses. If the caller does not need emails, avoid sending them.

### OWASP category

- A01: Broken Access Control
- A02: Cryptographic Failures / sensitive data exposure

### Recommendation

Return only the fields needed by the client.

```js
app.get('/users', requireAuth, requireRole('admin'), (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});
```

Or provide different views depending on authorization:

```js
app.get('/users', requireAuth, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  if (req.user.role !== 'admin') {
    return res.json(users.map(({ id, name }) => ({ id, name })));
  }

  res.json(users);
});
```

