# Suggested hardened version of `app.js`

Below is a more secure baseline version. This assumes API-key authentication for simplicity. In production, use your organization’s preferred auth mechanism.

```js
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

app.disable('x-powered-by');

app.use(helmet());

app.use(express.json({ limit: '100kb' }));

app.use(morgan('combined'));

const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests' },
});

app.use(generalLimiter);

function requireApiKey(req, res, next) {
  const expectedKey = process.env.API_KEY;
  const providedKey = req.get('x-api-key');

  if (!expectedKey) {
    console.error('API_KEY environment variable is not configured');
    return res.status(500).json({ error: 'Server misconfiguration' });
  }

  if (!providedKey || providedKey !== expectedKey) {
    console.warn('Unauthorized request', {
      ip: req.ip,
      path: req.originalUrl,
    });

    return res.status(401).json({ error: 'Unauthorized' });
  }

  next();
}

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

app.get('/users', requireApiKey, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
  });
});

app.use((err, req, res, next) => {
  console.error('Unhandled application error:', err);

  res.status(err.status || 500).json({
    error: 'Internal server error',
  });
});

const port = process.env.PORT || 3000;

if (require.main === module) {
  app.listen(port, () => {
    console.log(`Server running on port ${port}`);
  });
}

module.exports = app;
```

Required packages:

```bash
npm install helmet express-rate-limit morgan
```

Run with:

```bash
API_KEY='replace-with-a-strong-random-secret' PORT=3000 node app.js
```

