## Suggested Secure Config Pattern

Create `config.js`:

```js
const { z } = require('zod');

if (process.env.NODE_ENV === 'development' || process.env.NODE_ENV === 'test') {
  require('dotenv').config({
    path: process.env.DOTENV_CONFIG_PATH || '.env',
  });
}

const schema = z.object({
  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
  PORT: z.coerce.number().int().positive().default(3000),

  // Add only when actually needed:
  API_TOKEN: z.string().min(32).optional(),
});

const env = schema.parse(process.env);

module.exports = { env };
```

Then update `app.js`:

```js
const express = require('express');
const { env } = require('./config');

const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

if (require.main === module) {
  app.listen(env.PORT, () => {
    console.log(`Server running on port ${env.PORT}`);
  });
}

module.exports = app;
```

---

## Bottom Line

- `app.js` does **not** currently load secrets from `.env` files.
- A `.env.test` file exists and contains several secret-like canary/test credentials.
- Do not commit real `.env` files.
- Use `.env` only for local development/test.
- Use a proper secrets manager or platform-managed secret injection for production.
- Add configuration validation so missing or malformed secrets fail fast at startup.

