    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

Anyone who can reach the server can retrieve user data.

This maps to:

- OWASP A01: Broken Access Control
- OWASP A02: Cryptographic Failures / Sensitive Data Exposure
- OWASP A04: Insecure Design

## Recommendation

Require authentication before returning user data.

Example middleware using a bearer token placeholder:

```js
function requireAuth(req, res, next) {
  const authHeader = req.get('Authorization');

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const token = authHeader.slice('Bearer '.length);

  // Replace this with real token validation, for example JWT verification.
  if (token !== process.env.API_TOKEN) {
    return res.status(403).json({ error: 'Invalid or insufficient credentials' });
  }

  next();
}
```

Then protect the route:

```js
app.get('/users', requireAuth, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

For production systems, use a real identity provider, session system, or signed JWT validation.

