```

## Recommendation

Return only the fields needed by the client. Avoid returning email addresses unless required.

Example:

```js
app.get('/users', requireAuth, (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});
```

If email addresses are needed, enforce role-based authorization:

```js
function requireRole(role) {
  return (req, res, next) => {
    if (!req.user || req.user.role !== role) {
      return res.status(403).json({ error: 'Forbidden' });
    }

    next();
  };
}

app.get('/users', requireAuth, requireRole('admin'), (req, res) => {
  res.json([
