- Which user records should a caller see?
- Should email addresses be returned?
- Are there roles?
- Is this an internal-only endpoint?
- Is the health endpoint public?

### Recommendation

Define endpoint-level access rules.

Example:

```js
function requireRole(role) {
  return function requireRoleMiddleware(req, res, next) {
    if (!req.user?.roles?.includes(role)) {
      return res.status(403).json({ error: 'Forbidden' });
    }

    next();
  };
}

app.get('/users', authenticateJwt, requireRole('admin'), async (req, res) => {
  res.json(await listUsers());
});
