## A07: Identification and Authentication Failures

### Issue

No authentication exists. This is especially important for `/users`.

### Recommendation

At minimum, protect sensitive endpoints.

Simple API-key example:

```js
function requireApiKey(req, res, next) {
  const providedKey = req.header('x-api-key');
  const expectedKey = process.env.API_KEY;

  if (!expectedKey) {
    return res.status(500).json({ error: 'Server authentication not configured' });
  }

  if (providedKey !== expectedKey) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  next();
}
```

However, be careful not to use plain string comparison for highly sensitive secrets if timing attacks are relevant. For stronger comparison:

```js
const crypto = require('crypto');

function safeCompare(a, b) {
  const aBuffer = Buffer.from(a || '');
  const bBuffer = Buffer.from(b || '');

  if (aBuffer.length !== bBuffer.length) {
    return false;
  }

  return crypto.timingSafeEqual(aBuffer, bBuffer);
}
```

Then:

```js
if (!safeCompare(providedKey, expectedKey)) {
  return res.status(401).json({ error: 'Unauthorized' });
}
```

