## 2. Authentication and Authorization

### Current Risk: Medium

The `/users` route exposes user email addresses publicly:

```js
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

Even though this is hardcoded demo data, in a real application this pattern would be considered risky because email addresses are personally identifiable information.

This maps to:

- OWASP A01: Broken Access Control
- OWASP A02: Cryptographic Failures / Sensitive Data Exposure
- OWASP A04: Insecure Design

### Recommendation

Require authentication for user data routes.

Example API key middleware:

```js
function requireApiKey(req, res, next) {
  const apiKey = req.header('x-api-key');

  if (!apiKey || apiKey !== process.env.API_KEY) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  next();
}

app.get('/users', requireApiKey, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

For production systems, prefer standards-based authentication such as:

- OAuth 2.0
- OpenID Connect
- JWTs with proper validation
- Session authentication with secure cookies

Example JWT-style middleware:

```js
const jwt = require('jsonwebtoken');

function requireAuth(req, res, next) {
  const authHeader = req.header('authorization');

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing bearer token' });
  }

  const token = authHeader.slice('Bearer '.length);

  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET, {
      algorithms: ['HS256']
    });

    req.user = payload;
    next();
  } catch {
    return res.status(401).json({ error: 'Invalid token' });
  }
}
```

Then:

```js
app.get('/users', requireAuth, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

Also consider authorization checks:

```js
function requireAdmin(req, res, next) {
  if (!req.user || req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  next();
}

app.get('/users', requireAuth, requireAdmin, (req, res) => {
  res.json(users);
});
```

---

## 3. Missing Input Validation

### Current Risk: Low

The current routes do not accept user input.

However, there is no validation framework or pattern in place. This can lead to vulnerabilities later when routes are expanded.

### Recommendation

Adopt validation early.

Example validating route params:

```js
const { z } = require('zod');

const userParamsSchema = z.object({
  id: z.coerce.number().int().positive()
});

app.get('/users/:id', requireAuth, (req, res, next) => {
  try {
    const { id } = userParamsSchema.parse(req.params);

    const user = users.find(u => u.id === id);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (err) {
    next(err);
  }
});
```

Central validation error handling:

```js
app.use((err, req, res, next) => {
  if (err.name === 'ZodError') {
    return res.status(400).json({
      error: 'Invalid request',
      details: err.errors
    });
  }

  next(err);
});
```

